'use strict';
const assert = require('node:assert/strict');
const { createParser, parse } = require('./src/csv');
const { toObjects } = require('./src/rows');

const cases = [
  ['', []],
  ['\uFEFF', []],
  ['\n', [['']]],
  ['\r\n\r\n', [[''], ['']]],
  ['a\rb\nc\r\nd', [['a'], ['b'], ['c'], ['d']]],
  ['a,b,\r\n', [['a', 'b', '']]],
  [',,', [['', '', '']]],
  ['""', [['']]],
  ['""""', [['"']]],
  ['"a,b","say ""hi"""\n', [['a,b', 'say "hi"']]],
  ['"a\r\nb\rc\nd",tail\r\n', [['a\r\nb\rc\nd', 'tail']]],
  ['a"b,"c"', [['a"b', 'c']]],
  ['\uFEFFa,\uFEFFb', [['a', '\uFEFFb']]],
  ['\uFEFF\uFEFF', [['\uFEFF']]],
  ['😀,"😎"', [['😀', '😎']]],
  ['a;"b;c";', [['a', 'b;c', '']], { delimiter: ';' }],
  ['a\tb', [['a', 'b']], { delimiter: '\t' }],
  ['a b', [['a', 'b']], { delimiter: ' ' }],
  ['a\ud800b', [['a', 'b']], { delimiter: '\ud800' }],
  ['a,b', [['a', 'b']], { delimiter: undefined, header: true }],
];
let partitions = 0;
for (const [text, expected, options] of cases) {
  if (!options?.header) assert.deepEqual(parse(text, options), expected);
  for (let a = 0; a <= text.length; a++) {
    for (let b = a; b <= text.length; b++) {
      const parser = createParser(options);
      const actual = [];
      for (const chunk of ['', text.slice(0, a), '', text.slice(a, b), '', text.slice(b), '']) {
        actual.push(...parser.push(chunk));
      }
      actual.push(...parser.end());
      assert.deepEqual(actual, expected, JSON.stringify({ text, a, b }));
      assert.deepEqual(parser.end(), []);
      assert.throws(() => parser.push(''), Error);
      partitions++;
    }
  }
  const parser = createParser(options);
  const actual = [];
  for (let i = 0; i < text.length; i++) actual.push(...parser.push(text[i]));
  actual.push(...parser.end());
  assert.deepEqual(actual, expected);
}

const timing = createParser();
assert.deepEqual(timing.push('a\r'), [['a']]);
assert.deepEqual(timing.push(''), []);
assert.deepEqual(timing.push('\n"b\r'), []);
assert.deepEqual(timing.push('\nc"\r'), [['b\r\nc']]);
assert.deepEqual(timing.push('\n\nx,'), [['']]);
assert.deepEqual(timing.end(), [['x', '']]);

for (const delimiter of ['', 'ab', '😀', '"', '\r', '\n', null, 1, {}, [], true]) {
  assert.throws(() => createParser({ delimiter }), RangeError);
}
const validated = createParser();
for (const chunk of [null, undefined, 1, {}, [], Buffer.from('a'), new String('a')]) {
  assert.throws(() => validated.push(chunk), TypeError);
}
assert.deepEqual(validated.push('good\n'), [['good']]);
assert.deepEqual(validated.end(), []);
assert.throws(() => parse(1), TypeError);

const errors = [
  ['"a" ', 1, false],
  ['a\r\n"b"x', 2, false],
  ['"a\r\nb\rc\nd"x', 4, false],
  ['"', 1, true],
  ['"a\r\nb\rc\n', 4, true],
  ['a\r"b\r\n', 3, true],
  ['"a""', 1, true],
];
for (const [text, line, atEnd] of errors) {
  for (let split = 0; split <= text.length; split++) {
    const parser = createParser();
    const check = error => error instanceof SyntaxError && error.message.includes(`line ${line}`);
    if (atEnd) {
      parser.push(text.slice(0, split));
      parser.push('');
      parser.push(text.slice(split));
      assert.throws(() => parser.end(), check);
    } else {
      assert.throws(() => {
        parser.push(text.slice(0, split));
        parser.push('');
        parser.push(text.slice(split));
      }, check);
    }
  }
}

const first = createParser();
const second = createParser();
first.push('"one');
assert.deepEqual(second.push('two\n'), [['two']]);
first.push('"');
assert.deepEqual(first.end(), [['one']]);
assert.deepEqual(second.end(), []);

assert.deepEqual(parse('', { header: true }), []);
assert.deepEqual(parse('a,b', { header: true }), []);
const objects = parse('x,x,x_2,x,__proto__,constructor,toString,\n1,2,3,4,5,6,7\n8', { header: true });
assert.deepEqual(Object.keys(objects[0]), ['x', 'x_2', 'x_2_2', 'x_3', '__proto__', 'constructor', 'toString', '']);
assert.deepEqual(Object.values(objects[0]), ['1', '2', '3', '4', '5', '6', '7', '']);
assert.deepEqual(Object.values(objects[1]), ['8', '', '', '', '', '', '', '']);
for (const object of objects) {
  assert.equal(Object.getPrototypeOf(object), Object.prototype);
  const descriptor = Object.getOwnPropertyDescriptor(object, '__proto__');
  assert.equal(descriptor.enumerable, true);
  assert.equal(descriptor.writable, true);
}
const records = Object.freeze([Object.freeze(['a', 'a']), Object.freeze(['1'])]);
assert.deepEqual(toObjects(records, Object.freeze({ header: true })), [{ a: '1', a_2: '' }]);
const header = Object.freeze(['x', 'x']);
assert.deepEqual(toObjects(Object.freeze([Object.freeze(['a', 'b', 'ignored'])]), Object.freeze({ header })), [{ x: 'a', x_2: 'b' }]);
assert.deepEqual(toObjects([['a'], ['b']], { header: [] }), [{}, {}]);
console.log(`CSV contract smoke checks passed: ${partitions} chunk partitions, emission timing, line errors, validation, lifecycle, and headers`);

